function spliceInto(list1: ListNode | null, a: number, b: number, list2: ListNode | null): ListNode | null {
  const read = (h: ListNode | null) => { const out: number[] = []; for (; h; h = h.next) out.push(h.val); return out; };
  const x = read(list1), y = read(list2);
  const vals = [...x.slice(0, a), ...y, ...x.slice(b + 1)];
  let head: ListNode | null = null;
  for (let i = vals.length - 1; i >= 0; i--) head = new ListNode(vals[i], head);
  return head;
}

