class Solution:
    def spliceInto(self, list1: Optional[ListNode], a: int, b: int, list2: Optional[ListNode]) -> Optional[ListNode]:
        def read(h):
            out = []
            while h:
                out.append(h.val)
                h = h.next
            return out

        x, y = read(list1), read(list2)
        head = None
        for v in reversed(x[:a] + y + x[b + 1:]):
            head = ListNode(v, head)
        return head

