function spliceInto(list1: ListNode | null, a: number, b: number, list2: ListNode | null): ListNode | null {
  let before = list1!;
  for (let i = 0; i < a - 1; i++) before = before.next!;
  let after = before;
  for (let i = a - 1; i < b + 1; i++) after = after.next!;
  before.next = list2;
  let tail = list2!;
  while (tail.next) tail = tail.next;
  tail.next = after;
  return list1;
}

